-- Generated by Supabase CLI 3.1.0, then numbered to the repository convention.
-- EXPAND ONLY. Existing CFC writers remain usable until the explicit cutover.
-- Catalog verified 2026-11-14. No warehouse/history definitions are changed.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SELECT table_name,column_name,data_type FROM information_schema.columns
WHERE table_schema='public' AND table_name IN
 ('team_email_map','cfc_big_board_tiers','cfc_big_board_rankings','cfc_big_board_stars',
  'cfc_director_memos','cfc_team_manual_value_overrides','cfc_team_roster_players',
  'draft_log','draft_state','trade_offers','trade_threads','trade_messages',
  'cfc_pending_trade_overlays','league_memberships') ORDER BY table_name,ordinal_position;

-- These are NEW runtime objects, deliberately separate from historical ff_master_*.
CREATE TABLE IF NOT EXISTS public.cfc_league_runtime (
 league_id text PRIMARY KEY CHECK(length(league_id) BETWEEN 1 AND 100),
 revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0),
 source_revision bigint NOT NULL DEFAULT 0 CHECK(source_revision>=0),
 source_observed_at timestamptz, initialized_at timestamptz,
 roster_ids text[] NOT NULL DEFAULT '{}', writes_enabled boolean NOT NULL DEFAULT false
);
CREATE TABLE IF NOT EXISTS public.cfc_asset_ownership (
 league_id text NOT NULL REFERENCES public.cfc_league_runtime(league_id),
 asset_key text NOT NULL CHECK(length(asset_key) BETWEEN 3 AND 120),
 asset_kind text NOT NULL CHECK(asset_kind IN ('player','pick')),
 owner_roster_id text, consumed boolean NOT NULL DEFAULT false,
 source_owner_roster_id text, source_consumed boolean NOT NULL DEFAULT false,
 pending_local boolean NOT NULL DEFAULT false,
 last_mutation_revision bigint NOT NULL DEFAULT 0,
 draft_season integer, draft_pick_index integer,
 updated_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(league_id,asset_key),
 CHECK((asset_kind='player' AND asset_key ~ '^player:[A-Za-z0-9_-]+$') OR
       (asset_kind='pick' AND asset_key ~ '^pick:[0-9]{4}-[1-9][0-9]*-[A-Za-z0-9_-]+$')),
 CHECK((draft_season IS NULL)=(draft_pick_index IS NULL))
);
CREATE INDEX IF NOT EXISTS cfc_asset_owner_idx ON public.cfc_asset_ownership(league_id,owner_roster_id);
CREATE TABLE IF NOT EXISTS public.cfc_draft_slots (
 league_id text NOT NULL, draft_season integer NOT NULL CHECK(draft_season BETWEEN 2000 AND 2200),
 pick_index integer NOT NULL CHECK(pick_index>=0), asset_key text NOT NULL,
 round integer NOT NULL CHECK(round>0), slot integer NOT NULL CHECK(slot>0),
 PRIMARY KEY(league_id,draft_season,pick_index),
 UNIQUE(league_id,draft_season,asset_key),
 FOREIGN KEY(league_id,asset_key) REFERENCES public.cfc_asset_ownership(league_id,asset_key)
);
CREATE TABLE IF NOT EXISTS public.cfc_runtime_commands (
 league_id text NOT NULL REFERENCES public.cfc_league_runtime(league_id),
 actor_user_id uuid NOT NULL, request_id uuid NOT NULL,
 operation text NOT NULL, payload_hash text NOT NULL,
 result jsonb NOT NULL CHECK(jsonb_typeof(result)='object'),
 created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(league_id,actor_user_id,request_id)
);
COMMENT ON COLUMN public.cfc_runtime_commands.actor_user_id IS
 'All-zero UUID denotes a narrowly scoped service-only machine command; never an impersonated user.';
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['cfc_league_runtime','cfc_asset_ownership','cfc_draft_slots','cfc_runtime_commands'] LOOP
  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated,service_role',t);
 END LOOP;
END $$;

-- The legacy default is TEMPORARY expansion compatibility, removed at cutover.
-- The verified unscoped data belongs to the existing CFC Sleeper league.
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='team_email_map' AND column_name='league_id')
 AND EXISTS(SELECT 1 FROM public.team_email_map e JOIN auth.users u ON lower(u.email)=lower(e.email)
  JOIN public.league_memberships m ON m.user_id=u.id WHERE m.league_id<>'1328902558617473024') THEN
  RAISE EXCEPTION 'Unscoped invitation map has non-CFC memberships; explicit reviewed mapping is required before expansion';
 END IF;
END $$;
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['team_email_map','cfc_big_board_tiers','cfc_big_board_rankings',
  'cfc_big_board_stars','cfc_director_memos','cfc_team_manual_value_overrides','cfc_team_roster_players'] LOOP
  IF to_regclass('public.'||t) IS NULL THEN CONTINUE; END IF;
  EXECUTE format('ALTER TABLE public.%I ADD COLUMN IF NOT EXISTS league_id text',t);
  EXECUTE format('UPDATE public.%I SET league_id=%L WHERE league_id IS NULL',t,'1328902558617473024');
  EXECUTE format('ALTER TABLE public.%I ALTER COLUMN league_id SET DEFAULT %L',t,'1328902558617473024');
  EXECUTE format('ALTER TABLE public.%I ALTER COLUMN league_id SET NOT NULL',t);
  EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON public.%I(league_id)',t||'_league_idx',t);
  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',t);
 END LOOP;
END $$;
-- Add tenant uniqueness now; retain old ON CONFLICT targets until cutover.
DO $$ DECLARE t text; cols text; BEGIN
 FOR t,cols IN SELECT * FROM (VALUES
  ('team_email_map','email'),('cfc_big_board_tiers','roster_id,tier_order'),
  ('cfc_big_board_rankings','roster_id,player_id'),('cfc_big_board_stars','roster_id,player_id'),
  ('cfc_team_manual_value_overrides','team_id,asset_key'),('cfc_team_roster_players','team_id,sleeper_player_id')
 ) x(t,c) LOOP
  IF to_regclass('public.'||t) IS NULL THEN CONTINUE; END IF;
  EXECUTE format('CREATE UNIQUE INDEX IF NOT EXISTS %I ON public.%I(league_id,%s)',t||'_league_identity_key',t,cols);
 END LOOP;
 IF to_regclass('public.cfc_big_board_tiers') IS NOT NULL THEN
  CREATE UNIQUE INDEX IF NOT EXISTS cfc_big_board_tiers_scope_key ON public.cfc_big_board_tiers(league_id,roster_id,id);
  IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cfc_big_board_rankings_tenant_tier_fk'
     AND conrelid='public.cfc_big_board_rankings'::regclass) THEN
   ALTER TABLE public.cfc_big_board_rankings ADD CONSTRAINT cfc_big_board_rankings_tenant_tier_fk
    FOREIGN KEY(league_id,roster_id,tier_id) REFERENCES public.cfc_big_board_tiers(league_id,roster_id,id)
    ON DELETE SET NULL(tier_id);
  END IF;
 END IF;
END $$;

ALTER TABLE public.draft_log ADD COLUMN IF NOT EXISTS draft_season integer;
ALTER TABLE public.draft_log ADD COLUMN IF NOT EXISTS cfc_year integer GENERATED ALWAYS AS
 (CASE WHEN submitted_at IS NULL THEN NULL ELSE extract(year FROM submitted_at AT TIME ZONE 'UTC')::integer END) STORED;
ALTER TABLE public.draft_log ADD COLUMN IF NOT EXISTS runtime_revision bigint;
UPDATE public.draft_log SET draft_season=coalesce(cfc_year,extract(year FROM now() AT TIME ZONE 'UTC')::integer)
 WHERE draft_season IS NULL;
-- Legacy deployment omits season during expand; the cutover removes this default.
ALTER TABLE public.draft_log ALTER COLUMN draft_season SET DEFAULT extract(year FROM now() AT TIME ZONE 'UTC')::integer;
ALTER TABLE public.draft_log ALTER COLUMN draft_season SET NOT NULL;
ALTER TABLE public.draft_state ADD COLUMN IF NOT EXISTS draft_season integer;
ALTER TABLE public.draft_state ADD COLUMN IF NOT EXISTS team_count integer;
ALTER TABLE public.draft_state ADD COLUMN IF NOT EXISTS round_count integer;
ALTER TABLE public.draft_state ADD COLUMN IF NOT EXISTS pick_seconds integer;
-- Preserve CFC's actual application format, not the provider's larger draft settings.
UPDATE public.draft_state SET draft_season=coalesce(draft_season,2026),team_count=coalesce(team_count,12),
 round_count=coalesce(round_count,1),pick_seconds=coalesce(pick_seconds,1800)
 WHERE league_id='1328902558617473024';
CREATE UNIQUE INDEX IF NOT EXISTS draft_log_season_pick_key ON public.draft_log(league_id,draft_season,pick_index);
CREATE UNIQUE INDEX IF NOT EXISTS draft_log_season_player_key ON public.draft_log(league_id,draft_season,player_id) WHERE player_id IS NOT NULL;

-- Fail on orphan/cross-tenant links rather than silently discarding or moving data.
CREATE UNIQUE INDEX IF NOT EXISTS trade_threads_league_id_key ON public.trade_threads(league_id,id);
-- Confirmed live columns missing from the historical CI fixture.
ALTER TABLE public.trade_offers ADD COLUMN IF NOT EXISTS ai_quip text;
ALTER TABLE public.trade_offers ADD COLUMN IF NOT EXISTS from_base_value integer;
ALTER TABLE public.trade_offers ADD COLUMN IF NOT EXISTS to_base_value integer;
ALTER TABLE public.trade_offers ADD COLUMN IF NOT EXISTS asset_summary jsonb;
ALTER TABLE public.trade_offers ALTER COLUMN from_value DROP NOT NULL;
ALTER TABLE public.trade_offers ALTER COLUMN to_value DROP NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS trade_offers_league_id_key ON public.trade_offers(league_id,id);
DO $$ DECLARE t text; n text; f text; ref text; BEGIN
 FOR t,n,f,ref IN SELECT * FROM (VALUES
  ('trade_offers','trade_offers_tenant_thread_fk','thread_id','trade_threads'),
  ('trade_offers','trade_offers_tenant_parent_fk','parent_offer_id','trade_offers'),
  ('trade_messages','trade_messages_tenant_thread_fk','thread_id','trade_threads'),
  ('cfc_pending_trade_overlays','cfc_pending_trade_overlays_tenant_offer_fk','offer_id','trade_offers')
 ) x(t,n,f,r) LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname=n AND conrelid=to_regclass('public.'||t)) THEN
   EXECUTE format('ALTER TABLE public.%I ADD CONSTRAINT %I FOREIGN KEY(league_id,%I) REFERENCES public.%I(league_id,id)',t,n,f,ref);
  END IF;
 END LOOP;
 FOREACH t IN ARRAY ARRAY['trade_offers','trade_threads','trade_messages'] LOOP
  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',t);
 END LOOP;
END $$;
COMMIT;
